def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(p,d):p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
def load(p):return [json.loads(l) for l in p.read_text().splitlines() if l.strip()]
def audit_events(path):
 bad=[];errors=[];completed=0;models=[]
 for li,line in enumerate(path.read_text().splitlines(),1):
  if not line.strip():continue
  try:e=json.loads(line)
  except ValueError:bad.append({'line':li,'reason':'non_json'});continue
  et=e.get('type');it=e.get('item',{}).get('type') if isinstance(e.get('item',{}),dict) else None
  if it is not None and it not in {'agent_message','reasoning'}:bad.append({'line':li,'reason':'non_message_item'})
  if isinstance(et,str) and any(s in et.lower() for s in ['tool_call','function_call','web_search','web_fetch','command_execution']):bad.append({'line':li,'reason':'tool_event_type'})
  if et=='turn.completed':completed+=1
  if et in {'error','turn.failed'}:errors.append(e)
  for key in ['model','model_name']:
   if isinstance(e.get(key),str):models.append(e[key])
 return bad,errors,completed,models
